// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool ok;
        vm.prank(address(this));
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 ownerBalance = c.balanceOf(address(this));
        uint256 totalDistributed = c.totalDistributed();

        assertTrue(ok && ownerBalance == totalDistributed);
    }
}
